ins as (insert into public.user_ach(user_id,code,label,bonus,by)
 select p.id,v.code,v.label,v.bonus,(select id from public.profiles where full_name='Игорь Шубчик') from v join public.profiles p on p.full_name=any(v.names) and p.status='approved'
 on conflict(user_id,code) do nothing returning user_id)
insert into public.notifications(kind,title,body,link,to_user) select 'ach','🏅 Тебе выдали новые значки','Новых значков: '||count(*)||'. Загляни в «Игру», раздел достижений.','game',user_id from ins group by user_id;
insert into public.gacha_state(user_id) select id from public.profiles where full_name in('Кристина Прошутинская','Мария Ярошенко') on conflict do nothing;
update public.gacha_state set spent=spent-30 where user_id in(select id from public.profiles where full_name in('Кристина Прошутинская','Мария Ярошенко'));
select (select count(*) from public.user_ach where code ~ '^(adm|trn:(electro|verkholaz|rescue|cash)|spec:(alpha|ropes_all))') granted;
